import { expect, test, type Page } from "@playwright/test";
import { createHash } from "node:crypto";

async function signIn(page: Page) {
  await page.goto("/");
  await page.getByRole("button", { name: "Sign in with Google" }).click();
}

test.beforeEach(async ({ page, context, request }) => {
  // Independent actors also have independent IP rate-limit buckets. Production
  // rate limiting remains active, rather than adding a test-only auth bypass.
  const address = createHash("sha256").update(test.info().testId).digest();
  await context.setExtraHTTPHeaders({
    "x-forwarded-for": `10.${address[0]}.${address[1]}.${address[2]}`,
  });
  await request.post("http://127.0.0.1:3101/control", { data: { reset: true } });
  await page.route("https://accounts.google.com/o/oauth2/v2/auth**", async (route) => {
    const response = await request.post("http://127.0.0.1:3101/authorize", {
      data: { url: route.request().url() },
    });
    const { callback } = await response.json();
    await route.fulfill({ status: 302, headers: { location: callback } });
  });
