test("concurrent first sign-ins preserve one stable identity binding", async ({
  page,
  context,
  request,
}) => {
  // Independent browser sessions share Google's identity, not application cookies.
  const second = await context.browser()!.newContext({
    baseURL: "http://localhost:3100",
    extraHTTPHeaders: { "x-forwarded-for": "198.51.100.1" },
  });
  const other = await second.newPage();
  await other.route("https://accounts.google.com/o/oauth2/v2/auth**", async (route) => {
    const response = await request.post("http://127.0.0.1:3101/authorize", {
      data: { url: route.request().url() },
    });
    const { callback } = await response.json();
    await route.fulfill({ status: 302, headers: { location: callback } });
  });
  try {
    await Promise.all([signIn(page), signIn(other)]);
    await Promise.all([
      expect(page).toHaveURL(/\/profile|error=/),
      expect(other).toHaveURL(/\/profile|error=/),
    ]);
    expect(
      [page.url(), other.url()].filter((url) => new URL(url).pathname === "/profile").length,
    ).toBeGreaterThan(0);
    await request.post("http://127.0.0.1:3101/control", {
      data: { email: "concurrent-renamed@workspace.example" },
    });
    for (const browser of [page, other]) {
      if (new URL(browser.url()).pathname !== "/profile") await signIn(browser);
      else await browser.reload();
      await expect(
        browser.getByText("concurrent-renamed@workspace.example", { exact: true }),
      ).toBeVisible();
    }
  } finally {
    await second.close();
  }
});

